class Solution {
public:
    int getMoneyAmount(int n) {
        vector<vector<int>> dp(n + 2, vector<int>(n + 2, 0));
        vector<vector<int>> opt(n + 2, vector<int>(n + 2, 0));

        for (int i = 1; i <= n; i++) {
            opt[i][i] = i;
        }

        for (int len = 2; len <= n; len++) {
            for (int lo = 1; lo + len - 1 <= n; lo++) {
                int hi = lo + len - 1;
                int best = INT_MAX;
                int startK = opt[lo][hi - 1];
                int endK = opt[lo + 1][hi];
                for (int k = startK; k <= endK; k++) {
                    int cost = k + max(dp[lo][k - 1], dp[k + 1][hi]);
                    if (cost < best) {
                        best = cost;
                        opt[lo][hi] = k;
                    }
                }
                dp[lo][hi] = best;
            }
        }

        return dp[1][n];
    }
};
